package com.aistock.scheduler.task;
import java.time.*;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.stereotype.Repository;
@Repository public class RevisionScanRepository {
 private final JdbcTemplate jdbc;private final TaskRepository tasks;private final TransactionTemplate tx;
 public RevisionScanRepository(JdbcTemplate jdbc,TaskRepository tasks){this.jdbc=jdbc;this.tasks=tasks;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);}
 public Cursor cursor(Instant now){return tx.execute(s->{jdbc.update("insert into verification_revision_scan(plan_id,updated_at) values(1,?) on duplicate key update plan_id=plan_id",Timestamp.from(now));var c=locked();return advanceCutoff(c,now);});}
 public boolean begin(Cursor c,RevisionClient.Event e,LocalDate cutoff,Instant now){if(e==null||e.eventId()<=c.completedEventId()||!e.instrumentId().matches("(SH|SZ)[0-9]{6}")||!HttpPredictionTaskClient.uuid(e.rawVersionId())||cutoff==null||cutoff.isBefore(LocalDate.of(1990,1,1))||cutoff.isAfter(now.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate()))throw new IllegalArgumentException("Invalid revision event");return Boolean.TRUE.equals(tx.execute(s->{if(!locked().equals(c)||c.event()!=null)return false;jdbc.update("update verification_revision_scan set event_id=?,instrument_id=?,raw_version_id=?,cutoff_date=?,after_id=null,revision=revision+1,updated_at=? where plan_id=1",e.eventId(),e.instrumentId(),e.rawVersionId(),cutoff,Timestamp.from(now));return true;}));}
 public boolean publish(Cursor c,PredictionTaskClient.Page p,Instant now){validate(c,p);return Boolean.TRUE.equals(tx.execute(s->{if(!locked().equals(c))return false;if(!advanceCutoff(c,now).equals(c))return false;for(var i:p.items()){String key=revisionKey(c.event(),i);tasks.createVerification(i.predictionId(),i.instrumentId(),i.dueThrough(),i.ruleVersion(),key,now);}if(p.nextCursor()==null)jdbc.update("update verification_revision_scan set completed_event_id=event_id,event_id=null,instrument_id=null,raw_version_id=null,cutoff_date=null,after_id=null,revision=revision+1,updated_at=? where plan_id=1",Timestamp.from(now));else jdbc.update("update verification_revision_scan set after_id=?,revision=revision+1,updated_at=? where plan_id=1",p.nextCursor(),Timestamp.from(now));return true;}));}
 private Cursor advanceCutoff(Cursor c,Instant now){var local=now.atZone(ZoneId.of("Asia/Shanghai"));var cutoff=local.toLocalDate().minusDays(local.getHour()<20?1:0);if(c.event()!=null&&c.cutoffDate().isBefore(cutoff)){jdbc.update("update verification_revision_scan set cutoff_date=?,after_id=null,revision=revision+1,updated_at=? where plan_id=1",cutoff,Timestamp.from(now));return locked();}return c;}
 static String revisionKey(RevisionClient.Event e,PredictionTaskClient.Item i){try{String identity=String.join("|",i.predictionId(),Long.toString(e.eventId()),e.rawVersionId(),i.ruleVersion(),i.dueThrough().toString());return "raw-"+java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(identity.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException ex){throw new IllegalStateException("SHA-256 unavailable");}}
 private void validate(Cursor c,PredictionTaskClient.Page p){if(c.event()==null||p==null||!c.cutoffDate().equals(p.cutoffDate())||p.items().size()>50)throw new IllegalArgumentException("Invalid revision page");String previous=c.afterId()==null?"":c.afterId();for(var i:p.items()){if(!HttpPredictionTaskClient.uuid(i.predictionId())||i.predictionId().compareTo(previous)<=0||!c.event().instrumentId().equals(i.instrumentId())||i.dueThrough()==null||i.dueThrough().isAfter(c.cutoffDate()))throw new IllegalArgumentException("Invalid revision item");previous=i.predictionId();}if(p.nextCursor()!=null&&(p.items().isEmpty()||!p.nextCursor().equals(previous)))throw new IllegalArgumentException("Invalid revision cursor");}
 private Cursor locked(){return jdbc.queryForObject("select * from verification_revision_scan where plan_id=1 for update",(r,n)->{long event=r.getLong("event_id");RevisionClient.Event e=r.wasNull()?null:new RevisionClient.Event(event,r.getString("instrument_id"),r.getString("raw_version_id"));var date=r.getDate("cutoff_date");return new Cursor(r.getLong("completed_event_id"),e,date==null?null:date.toLocalDate(),r.getString("after_id"),r.getLong("revision"));});}
 public record Cursor(long completedEventId,RevisionClient.Event event,LocalDate cutoffDate,String afterId,long revision){}
}
